from dataclasses import dataclass

import pytest


@dataclass
class Num:
    v: int


@dataclass
class Add:
    l: "Expr"
    r: "Expr"


@dataclass
class Mul:
    l: "Expr"
    r: "Expr"


Expr = Num | Add | Mul


def eval_expr(e: Expr) -> int:
    """Evaluate an arithmetic expression tree.

    Num yields its value, Add yields the sum of its children,
    and Mul yields the product of its children.
    """
    if isinstance(e, Num):
        return e.v
    if isinstance(e, Add):
        return eval_expr(e.l) + eval_expr(e.r)
    return eval_expr(e.l) * eval_expr(e.r)


def test_eval_num() -> None:
    assert eval_expr(Num(7)) == 7


def test_eval_add() -> None:
    assert eval_expr(Add(Num(2), Num(3))) == 5


def test_eval_mul() -> None:
    assert eval_expr(Mul(Num(4), Num(5))) == 20


def test_eval_nested() -> None:
    # (2 + 3) * (4 + -1) = 15
    e: Expr = Mul(Add(Num(2), Num(3)), Add(Num(4), Num(-1)))
    assert eval_expr(e) == 15


def test_eval_deep_left_chain() -> None:
    e: Expr = Num(1)
    for _ in range(10):
        e = Add(e, Num(1))
    assert eval_expr(e) == 11


@pytest.mark.parametrize(
    ("expr", "expected"),
    [
        (Num(0), 0),
        (Mul(Num(0), Num(99)), 0),
        (Add(Mul(Num(2), Num(2)), Num(-4)), 0),
    ],
)
def test_eval_parametrized(expr: Expr, expected: int) -> None:
    assert eval_expr(expr) == expected
